// Interaction polish layered over the initial gallery screens.
const originalRender = window.__aluBaseRender;
let conversations = [];
let contacts = [];
let activeConversation = null;
let messageRows = [];
let conversationsLoading = false;
let conversationsLoaded = false;
let notifications = (window.__ALU_BOOTSTRAP__?.notifications||[]).map(n=>({...n,read:!!n.read_at}));
let setupAvailable=!!window.__ALU_BOOTSTRAP__?.setupAvailable;

function persist() { save(); }
function addNotification(text) { notifications.unshift({text, date:new Date().toLocaleString(), read:false}); }
const displayStatus=s=>String(s||'').replace(/\b\w/g,c=>c.toUpperCase());
function formatDate(value,withTime=false){if(!value)return 'Date to be announced';const date=new Date(value);if(Number.isNaN(date.getTime()))return value;return new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric',...(withTime?{hour:'numeric',minute:'2-digit'}:{})}).format(date);}
function hydrateData(data){return {artworks:(data.artworks||[]).map(x=>({...x,status:displayStatus(x.status)})),artists:data.artists||[],exhibitions:(data.exhibitions||[]).map(x=>({...x,date:formatDate(x.date),endsAt:formatDate(x.ends_at),status:displayStatus(x.status)})),institutions:(data.institutions||[]).map(x=>({...x,artists:x.artists||0,approved:x.status==='approved'})),events:(data.events||[]).map(x=>({...x,status:displayStatus(x.status),date:formatDate(x.date,true),image:'',registered:!!x.registered})),submissions:(data.submissions||[]).map(x=>({...x,status:displayStatus(x.status)})),requests:(data.collaborations||[]).map(x=>({...x,status:displayStatus(x.status)})),messages:[],reports:data.reports||null};}
async function api(path,options={}) {
  const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  const result=await response.json().catch(()=>({error:'The server returned an unreadable response.'}));
  if(!response.ok) throw new Error(result.error||`Request failed (${response.status}).`);
  return result;
}
async function refreshFromServer() {
  const data=await api('/api/bootstrap');
  const previousId=signedUser?.id;
  signedUser=data.user;
  setupAvailable=!!data.setupAvailable;
  if(previousId!==signedUser?.id){reportData=null;userRecords=null;conversationsLoaded=false;conversations=[];contacts=[];messageRows=[];activeConversation=null;}
  role=signedUser?.role==='gallery_admin'?'Gallery admin':signedUser?.role==='institution_admin'?'Institution admin':signedUser?.role==='artist'?'Artist':'Public visitor';
  if(!signedUser&&['Dashboard','Submissions','Collaborations','Messages','Reports'].includes(page))page='Home';
  db=hydrateData(data);
  notifications=(data.notifications||[]).map(n=>({...n,read:!!n.read_at}));
  conversationsLoaded=false;
  render();
}
async function loadConversations() {
  if(conversationsLoading||conversationsLoaded||!signedUser)return;
  conversationsLoading=true;
  try{const [c,u]=await Promise.all([api('/api/messages'),api('/api/contacts')]);conversations=c.conversations||[];contacts=u.contacts||[];if(activeConversation&&!conversations.some(x=>x.id===activeConversation))activeConversation=null;if(activeConversation)messageRows=(await api(`/api/messages/${activeConversation}`)).messages||[];else messageRows=[];conversationsLoaded=true;}
  catch(err){toast(err.message);conversationsLoaded=true;}
  finally{conversationsLoading=false;render();}
}
const galleryDisciplines=['Painting','Sculpture','Photography','Textiles','Mixed media','Digital art','Drawing','Printmaking','Ceramics','Installation','Performance','Collage','Fiber art','Illustration','Video art'];
let galleryFilters={category:'',artist:'',institution:''};
function registrationFields(){return `<div class="field full"><label>I am registering as</label><div class="register-switch" role="group" aria-label="Choose account type"><button type="button" class="register-choice active" data-register-role="artist" aria-pressed="true">Artist / Student</button><button type="button" class="register-choice" data-register-role="institution_admin" aria-pressed="false">Institution</button></div><input type="hidden" name="role" id="registerRole" value="artist"></div><p class="field full institution-note" hidden>Institution accounts are reviewed by the ALU Gallery administrator before activation.</p><div class="field full artist-fields"><label>Institution affiliation <span class="optional">Optional</span></label><select name="institutionId"><option value="">Independent artist / student</option>${db.institutions.filter(i=>i.status==='approved').map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div class="field full institution-fields" hidden><label>Institution name</label><input name="institutionName" maxlength="150" placeholder="e.g. Nairobi School of Art"></div><div class="field institution-fields" hidden><label>Type</label><select name="institutionType"><option>University</option><option>Art gallery</option><option>Cultural institution</option><option>Creative organization</option></select></div><div class="field institution-fields" hidden><label>Country</label><input name="location" placeholder="Rwanda" maxlength="150"></div>`;}
gallery=function(){const options=(items,id,label,selected)=>`<select class="filter" id="${id}"><option value="">${label}</option>${items.map(x=>`<option value="${esc(x)}" ${selected===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;return `${head('Discover','Explore the gallery','Browse selected works from artists across our creative community.',role==='Artist'?'<button class="btn" data-modal="art">＋ Add artwork</button>':'')}<div class="toolbar gallery-filters"><input id="search" class="search" placeholder="Search artworks or artists" value="${esc(filter)}">${options(galleryDisciplines,'catfilter','All disciplines',galleryFilters.category)}${options([...new Set(db.artists.map(a=>a.fullName))],'artistfilter','All artists',galleryFilters.artist)}${options([...new Set(db.institutions.map(i=>i.name))],'institutionfilter','All institutions',galleryFilters.institution)}</div><div class="gallery-results">${cards(db.artworks.filter(a=>a.status==='Published'&&`${a.title} ${a.artist} ${a.category} ${a.institution||''}`.toLowerCase().includes(filter.toLowerCase())&&(!galleryFilters.category||a.category===galleryFilters.category)&&(!galleryFilters.artist||a.artist===galleryFilters.artist)&&(!galleryFilters.institution||a.institution===galleryFilters.institution)))}</div>`;};
function authDialog(mode='login') {
  if(mode==='setup'){
    document.querySelector('#modal').innerHTML='<div class="modalback" id="setupBackdrop"><section class="modal" role="dialog" aria-modal="true"><button class="detailclose" id="setupClose" aria-label="Close">×</button><div class="eyebrow">One-time setup</div><h2>Create gallery administrator</h2><form id="setupForm"><div class="formgrid"><div class="field full"><label>Setup key</label><input name="setupKey" type="password" required autocomplete="off"></div><div class="field full"><label>Full name</label><input name="fullName" required minlength="2"></div><div class="field full"><label>Email address</label><input name="email" type="email" required></div><div class="field full"><label>Password (at least 12 characters)</label><input name="password" type="password" required minlength="12"></div></div><p id="setupError" class="autherror" role="alert"></p><div class="formactions"><button class="btn">Create administrator</button></div></form><p class="authhelp">The setup key must be set on the server before this step is available.</p></section></div>';
    const close=()=>document.querySelector('#modal').innerHTML='';document.querySelector('#setupClose').onclick=close;document.querySelector('#setupBackdrop').onclick=e=>{if(e.target.id==='setupBackdrop')close();};document.querySelector('#setupForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,error=document.querySelector('#setupError'),button=form.querySelector('.btn');button.disabled=true;try{await api('/api/setup-admin',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});close();toast('Administrator created. Sign in to continue.');setupAvailable=false;authDialog('login');}catch(err){error.textContent=err.message;button.disabled=false;}};return;
  }
  const register=mode==='register';
  document.querySelector('#modal').innerHTML=`<div class="modalback" id="authBackdrop"><section class="modal auth-modal" role="dialog" aria-modal="true" aria-labelledby="authTitle"><button class="detailclose" id="authClose" aria-label="Close">×</button><div class="auth-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="10" cy="8" r="3.5"/><path d="M3.5 20v-1a6.5 6.5 0 0 1 13 0v1M19 7v6m-3-3h6"/></svg></div><h2 id="authTitle">${register?'Create your account':'Welcome back'}</h2><p class="auth-subtitle">${register?'Sign up to get started':'Sign in to continue'}</p><form id="authForm"><div class="formgrid">${register?registrationFields()+'<div class="field full"><label>Full name</label><input name="fullName" required minlength="2" maxlength="100" placeholder="Your full name" autocomplete="name"></div>':''}<div class="field full"><label>Email</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field full"><label>Password</label><input name="password" type="password" required minlength="${register?'12':'1'}" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 12 characters':'Your password'}"></div>${register?'<div class="field full"><label>Confirm password</label><input name="confirmPassword" type="password" required minlength="12" autocomplete="new-password" placeholder="Re-enter your password"></div>':''}</div><p class="autherror" id="authError" role="alert"></p><button class="btn auth-submit">${register?'Create account':'Sign in'}</button><div class="auth-switch">${register?'Already have an account?':'New to ALU Gallery?'} <button type="button" class="textbtn" id="authSwitch">${register?'Log in':'Create an account'}</button></div></form>${!register?'<p class="authhelp">Forgot your password? Password recovery needs an email service to be configured.</p>':''}</section></div>`;
  const close=()=>document.querySelector('#modal').innerHTML='';
  document.querySelector('#authClose').onclick=close;document.querySelector('#authBackdrop').onclick=e=>{if(e.target.id==='authBackdrop')close();};
  document.querySelector('#authSwitch').onclick=()=>authDialog(register?'login':'register');
  const roleSelect=document.querySelector('#registerRole');if(roleSelect)document.querySelectorAll('[data-register-role]').forEach(button=>button.onclick=()=>{roleSelect.value=button.dataset.registerRole;const institution=roleSelect.value==='institution_admin';document.querySelectorAll('[data-register-role]').forEach(x=>{const selected=x===button;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',String(selected));});document.querySelectorAll('.institution-fields').forEach(f=>{f.hidden=!institution;const input=f.querySelector('input,select');if(input&&input.name!=='institutionType')input.required=institution;});document.querySelectorAll('.artist-fields').forEach(f=>f.hidden=institution);document.querySelector('.institution-note').hidden=!institution;});
  document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form)),error=document.querySelector('#authError'),submit=form.querySelector('.auth-submit');submit.disabled=true;submit.textContent='Please wait…';error.textContent='';try{if(register){if(values.password!==values.confirmPassword)throw new Error('Your passwords do not match.');delete values.confirmPassword;const result=await api('/api/register',{method:'POST',body:JSON.stringify(values)});if(values.role==='institution_admin'){close();toast(result.message);return;}toast('Account created. Sign in with your email and password.');authDialog('login');}else{await api('/api/login',{method:'POST',body:JSON.stringify(values)});close();await refreshFromServer();toast(`Signed in as ${signedUser.fullName}.`);}}catch(err){error.textContent=err.message;submit.disabled=false;submit.textContent=register?'Create account':'Sign in';}};
}
async function openProfile(){try{const data=await api('/api/profile'),u=data.user,p=data.profile||{},i=data.institution||{};const artist=u.role==='artist',institution=u.role==='institution_admin';document.querySelector('#modal').innerHTML=`<div class="modalback" id="profileBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="profileTitle"><button class="detailclose" id="profileClose" aria-label="Close">×</button><div class="eyebrow">Account settings</div><h2 id="profileTitle">${institution?'Institution profile':artist?'Artist profile':'Administrator profile'}</h2><form id="profileForm"><div class="formgrid"><div class="field full"><label>Full name</label><input name="fullName" value="${esc(u.fullName)}" required minlength="2" maxlength="100"></div><div class="field full"><label>Email address</label><input value="${esc(u.email)}" disabled><small class="authhelp">Email changes require email verification, which needs an email service.</small></div>${artist?`<div class="field full"><label>Biography</label><textarea name="biography" maxlength="3000">${esc(p.biography||'')}</textarea></div><div class="field"><label>Country</label><input name="country" value="${esc(p.country||'')}"></div><div class="field"><label>Artistic discipline</label><input name="discipline" value="${esc(p.discipline||'')}"></div><div class="field full"><label>Areas of interest</label><input name="interests" value="${esc(p.interests||'')}"></div><div class="field full"><label>Portfolio URL</label><input name="portfolio" type="url" value="${esc(p.portfolio||'')}"></div><div class="field full"><label>Contact information</label><input name="contact" value="${esc(p.contact||'')}"></div><div class="field full"><label><input name="emailPublic" type="checkbox" ${p.emailPublic?'checked':''}> Show my email publicly</label></div>`:''}${institution?`<div class="field full"><label>Institution name</label><input name="institutionName" value="${esc(i.name||'')}" required></div><div class="field"><label>Institution type</label><input name="institutionType" value="${esc(i.type||'')}"></div><div class="field"><label>Location</label><input name="location" value="${esc(i.location||'')}"></div><div class="field full"><label>Description</label><textarea name="description">${esc(i.description||'')}</textarea></div><div class="field full"><label>Official website</label><input name="website" type="url" value="${esc(i.website||'')}"></div>`:''}</div><p class="autherror" id="profileError" role="alert"></p><div class="formactions"><button type="button" class="btn outline" id="profileCancel">Cancel</button><button class="btn">Save changes</button></div></form></section></div>`;const close=()=>document.querySelector('#modal').innerHTML='';document.querySelector('#profileClose').onclick=close;document.querySelector('#profileCancel').onclick=close;document.querySelector('#profileBackdrop').onclick=e=>{if(e.target.id==='profileBackdrop')close();};document.querySelector('#profileForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));values.emailPublic=e.currentTarget.elements.emailPublic?.checked||false;try{await api('/api/profile',{method:'PATCH',body:JSON.stringify(values)});close();await refreshFromServer();toast('Profile saved.');}catch(err){document.querySelector('#profileError').textContent=err.message;}};}catch(err){toast(err.message);}}
function accountControls() {
  const selector=document.querySelector('#roleSelect');if(selector)selector.hidden=true;
  const host=document.querySelector('.topright');if(!host)return;
  let box=document.querySelector('#accountControls');if(!box){box=document.createElement('div');box.id='accountControls';box.className='account-controls';host.appendChild(box);}
  box.innerHTML=signedUser?`<span class="account-name">${esc(signedUser.fullName)}</span><button class="btn outline small" id="profileButton">My profile</button><button class="btn outline small" id="logoutButton">Sign out</button>`:`${setupAvailable?'<button class="textbtn" data-auth="setup">Set up admin</button>':''}<button class="btn outline small" data-auth="login">Sign in</button><button class="btn small" data-auth="register">Register</button>`;
  document.querySelector('#profileButton')?.addEventListener('click',openProfile);
  const mini=document.querySelector('.profilemini');if(mini){const name=signedUser?.fullName||'Visitor',initials=name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();mini.innerHTML=`<div class="miniinitials" aria-hidden="true">${esc(initials)}</div><div><b>${esc(name)}</b><small>${esc(signedUser?.role?.replaceAll('_',' ')||'Public visitor')}</small></div>`;}
  document.querySelector('#logoutButton')?.addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});await refreshFromServer();toast('You are signed out.');}catch(err){toast(err.message);}});
}
artists=function(){return `${head('Creative community','Meet the artists','Discover artists whose work has been published in the gallery.')}<div class="grid">${db.artists.map(a=>`<article class="instcard"><div class="artistinitials" aria-hidden="true">${esc(a.fullName.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><h3>${esc(a.fullName)}</h3><p>${esc(a.discipline||'Artist')}${a.country?' · '+esc(a.country):''}</p><p>${esc(a.biography||'')}</p><div class="instmeta"><span>${a.works} published works</span><button class="textbtn" data-artist="${esc(a.fullName)}">View works →</button></div></article>`).join('')||'<div class="empty">Artist portfolios will appear when artwork is approved and published.</div>'}</div>`;};
function showArtwork(art) {
  document.querySelector('#modal').innerHTML=`<div class="modalback" id="backdrop"><section class="modal artdetail" role="dialog" aria-modal="true" aria-labelledby="detailTitle"><button class="detailclose" aria-label="Close" data-close>×</button><img src="${esc(art.image)}" alt="Artwork: ${esc(art.title)}"><div class="detailcopy"><div class="eyebrow">${esc(art.category)}</div><h2 id="detailTitle">${esc(art.title)}</h2><p class="detailartist">By ${esc(art.artist)}</p><p>${esc(art.description||'A work from the ALU Gallery collection.')}</p>${art.medium?`<p><b>Medium</b> · ${esc(art.medium)}</p>`:''}${art.copyright?`<p class="detail-credit">${esc(art.copyright)}</p>`:''}</div></section></div>`;
  document.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop'||e.target.closest('[data-close]'))close();};
}
cards=function(list){return list.length?`<div class="grid">${list.map(a=>{const canManage=signedUser&&(signedUser.role==='gallery_admin'||a.ownerId===signedUser.id||(a.institutionId&&a.institutionId===signedUser.institutionId));return `<article class="artcard"><img class="artimg" src="${esc(a.image)}" alt="Artwork: ${esc(a.title)}"><div class="artinfo"><h3>${esc(a.title)}</h3><p>${esc(a.artist)} · ${esc(a.category)}</p><span class="tag">${esc(a.status)}</span>${canManage?`<div class="art-management"><button class="textbtn" data-art-edit="${a.id}">Edit details</button><button class="textbtn" data-art-delete="${a.id}">Remove</button></div>`:''}</div></article>`;}).join('')}</div>`:'<div class="empty">No artworks found.</div>';};
function editArtwork(id){const art=db.artworks.find(x=>x.id===Number(id));if(!art)return;document.querySelector('#modal').innerHTML=`<div class="modalback" id="artEditBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="artEditTitle"><button class="detailclose" id="artEditClose" aria-label="Close">×</button><div class="eyebrow">Artwork management</div><h2 id="artEditTitle">Edit artwork</h2><form id="artEditForm"><div class="formgrid"><div class="field full"><label>Title</label><input name="title" required maxlength="180" value="${esc(art.title)}"></div><div class="field"><label>Discipline</label><input name="category" required value="${esc(art.category)}"></div><div class="field"><label>Medium and materials</label><input name="medium" value="${esc(art.medium||'')}"></div><div class="field"><label>Dimensions</label><input name="dimensions" value="${esc(art.dimensions||'')}"></div><div class="field"><label>Creation date</label><input name="creationDate" type="date" value="${esc(art.creationDate||'')}"></div><div class="field full"><label>Description</label><textarea name="description" maxlength="5000">${esc(art.description||'')}</textarea></div><div class="field full"><label>Tags</label><input name="tags" value="${esc(art.tags||'')}"></div><div class="field full"><label>Copyright / ownership</label><input name="copyright" value="${esc(art.copyright||'')}"></div></div><p class="autherror" id="artEditError" role="alert"></p><div class="formactions"><button type="button" class="btn outline" id="artEditCancel">Cancel</button><button class="btn">Save changes</button></div></form></section></div>`;const close=()=>document.querySelector('#modal').innerHTML='';document.querySelector('#artEditClose').onclick=close;document.querySelector('#artEditCancel').onclick=close;document.querySelector('#artEditBackdrop').onclick=e=>{if(e.target.id==='artEditBackdrop')close();};document.querySelector('#artEditForm').onsubmit=async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('button.btn');submit.disabled=true;submit.textContent='Saving…';try{await api(`/api/artworks/${art.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});close();await refreshFromServer();toast('Artwork details updated.');}catch(err){document.querySelector('#artEditError').textContent=err.message;submit.disabled=false;submit.textContent='Save changes';}};}
function showNotifications() {
  const list=notifications.length?notifications.slice(0,10).map(n=>`<div class="notificationrow"><i class="readmark ${n.read?'read':''}"></i><div><b>${esc(n.text)}</b><small>${esc(n.date)}</small></div></div>`).join(''):'<div class="empty">You are all caught up.</div>';
  document.querySelector('#modal').innerHTML=`<div class="modalback" id="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="noticeTitle"><div class="panelhead"><h2 id="noticeTitle">Notifications</h2><button class="textbtn" id="clearNotices">Clear all</button></div>${list}<div class="formactions"><button class="btn outline" data-close>Close</button></div></section></div>`;
  notifications.forEach(n=>n.read=true);persist();document.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop'||e.target.closest('[data-close]'))close();};document.querySelector('#clearNotices').onclick=async()=>{if(signedUser){try{await api('/api/notifications',{method:'DELETE'});}catch(err){toast(err.message);return;}}notifications=[];persist();showNotifications();render();};render();
}
function permitted(item) {
  const p=item.dataset.page;
  if(role==='Gallery admin') return true;
  if(role==='Institution admin') return ['Home','Gallery','Artists','Exhibitions','Institutions','Events','Dashboard','Submissions','Collaborations','Messages','Reports'].includes(p);
  if(role==='Artist') return ['Home','Gallery','Artists','Exhibitions','Institutions','Events','Submissions','Messages'].includes(p);
  return ['Home','Gallery','Artists','Exhibitions','Institutions','Events'].includes(p);
}
let reportData=null;
let userRecords=null;
function reportMarkup(){return `${head('Gallery administration','Reports and analytics','Filter platform activity and export a spreadsheet or print-ready report.')}<div class="panel"><form id="reportFilter" class="toolbar"><label class="datefilter">From <input type="date" name="from"></label><label class="datefilter">To <input type="date" name="to"></label><button class="btn small">Apply filters</button><button type="button" class="btn outline small" id="exportReport">Export Excel CSV</button><button type="button" class="btn outline small" id="printReport">Print / Save PDF</button></form><div id="reportResults">${reportData?reportStats(reportData):'<div class="empty">Loading report…</div>'}</div></div>`;}
function reportStats(d){return `<div class="stats">${[['Users',d.users],['Artists',d.artists],['Institutions',d.institutions],['Submissions',d.submissions],['Approved',d.approved],['Events',d.events]].map(x=>`<div class="stat"><label>${x[0]}</label><strong>${x[1]}</strong></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Month</th><th>Submissions</th></tr></thead><tbody>${(d.monthly||[]).map(x=>`<tr><td>${esc(x.month)}</td><td>${x.count}</td></tr>`).join('')||'<tr><td colspan="2">No activity in this date range.</td></tr>'}</tbody></table></div>`;}
async function fetchReport(from='',to=''){try{const q=new URLSearchParams();if(from)q.set('from',from);if(to)q.set('to',to);reportData=await api('/api/reports?'+q);const target=document.querySelector('#reportResults');if(target)target.innerHTML=reportStats(reportData);}catch(err){const target=document.querySelector('#reportResults');if(target)target.innerHTML=`<div class="empty">${esc(err.message)}</div>`;}}
function ensureReportsNav(){if(document.querySelector('[data-page="Reports"]'))return;const button=document.createElement('button');button.className='navbtn';button.dataset.page='Reports';button.innerHTML='<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 19V5m0 14h17M8 15l3-4 3 2 5-7"/></svg><span>▤</span><span>Reports</span>';button.onclick=()=>go('Reports');const side=document.querySelector('.side'),profile=document.querySelector('.profilemini');side.insertBefore(button,profile);}
function ensureUsersNav(){if(document.querySelector('[data-page="Users"]'))return;const button=document.createElement('button');button.className='navbtn';button.dataset.page='Users';button.innerHTML='<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="9" cy="8" r="3"/><path d="M3 20v-1a6 6 0 0 1 12 0v1m2-8a3 3 0 1 0 0-6m4 14v-1a6 6 0 0 0-4-5.65"/></svg><span>◉</span><span>Users</span>';button.onclick=()=>go('Users');const side=document.querySelector('.side'),profile=document.querySelector('.profilemini');side.insertBefore(button,profile);}
function usersMarkup(){return `${head('Gallery administration','User management','Manage account access across the partner network.')}<div class="panel"><div class="toolbar"><input class="search" id="userSearch" placeholder="Search people or institutions"></div><div id="userRows">${userRecords?userTable(userRecords):'<div class="empty">Loading accounts…</div>'}</div></div>`;}
dashboard=function(){const r=db.reports||{users:(db.institutions.find(i=>i.id===signedUser?.institutionId)?.artists||0)+1,artists:db.institutions.find(i=>i.id===signedUser?.institutionId)?.artists||0,institutions:1,submissions:db.submissions.length,pending:db.submissions.filter(s=>['Submitted','Under review'].includes(s.status)).length,publishedArtwork:db.artworks.filter(a=>a.status==='Published').length};const values=[['Registered users',r.users],['Artists',r.artists],['Institutions',r.institutions],['Submissions',r.submissions],['Published works',r.publishedArtwork],['Awaiting review',r.pending],['Upcoming exhibitions',db.exhibitions.filter(e=>['Upcoming','Open For Submissions'].includes(e.status)).length],['Active exhibitions',db.exhibitions.filter(e=>e.status==='Ongoing').length]];return `${head('Gallery administration','Overview','A snapshot of activity in your authorized workspace.')}<div class="stats">${values.map(x=>`<div class="stat"><label>${x[0]}</label><strong>${x[1]||0}</strong></div>`).join('')}</div><div class="panel"><div class="panelhead"><h3>Recent submissions</h3><button class="textbtn" data-go="Submissions">Review submissions →</button></div>${submissionTable(db.submissions.slice(0,7),role==='Gallery admin')}</div><div class="panel"><div class="panelhead"><h3>Upcoming exhibitions</h3><button class="textbtn" data-go="Exhibitions">All exhibitions →</button></div><div class="tablewrap"><table><thead><tr><th>Exhibition</th><th>Opening</th><th>Venue</th><th>Status</th></tr></thead><tbody>${db.exhibitions.map(e=>`<tr><td>${esc(e.title)}</td><td>${esc(e.date)}</td><td>${esc(e.place)}</td><td>${stat(e.status)}</td></tr>`).join('')||'<tr><td colspan="4">No exhibitions scheduled.</td></tr>'}</tbody></table></div></div>`;};
function userTable(list){return `<div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Institution</th><th>Status</th><th>Access</th></tr></thead><tbody>${list.map(u=>`<tr><td>${esc(u.fullName)}</td><td>${esc(u.email)}</td><td>${esc(u.role.replaceAll('_',' '))}</td><td>${esc(db.institutions.find(i=>i.id===u.institutionId)?.name||'—')}</td><td>${stat(u.status)}</td><td>${u.role==='gallery_admin'?'Administrator':`<button class="textbtn" data-user-status="${u.id}" data-status="${u.status==='active'?'suspended':'active'}">${u.status==='active'?'Suspend':'Activate'}</button>`}</td></tr>`).join('')||'<tr><td colspan="6">No accounts found.</td></tr>'}</tbody></table></div>`;}
async function loadUsers(){try{const data=await api('/api/users');userRecords=data.users||[];const target=document.querySelector('#userRows');if(target)target.innerHTML=userTable(userRecords);}catch(err){const target=document.querySelector('#userRows');if(target)target.innerHTML=`<div class="empty">${esc(err.message)}</div>`;}}
function aboutPage(){return `<div class="about-page-content"><section class="about-hero"><div class="about-inner"><div class="eyebrow">About</div><h1>ALU Gallery is a working gallery —<br>and a network for African creative practice.</h1><p>Founded at the African Leadership University in Kigali, the gallery holds and presents work by students and affiliated artists, and partners with universities, galleries and cultural organizations across the continent to co-curate exhibitions and share collections.</p></div></section><section class="about-principles"><article><span class="about-number">01</span><h2>Exhibition</h2><p>A rolling programme of curated exhibitions, both physical and online, presenting student and affiliated artists alongside invited voices.</p></article><article><span class="about-number">02</span><h2>Collaboration</h2><p>Partner universities, galleries and cultural organizations participate through collaborative exhibitions, shared submissions and stewardship of their own artists.</p></article><article><span class="about-number">03</span><h2>Stewardship</h2><p>Every work enters the collection through a documented review, submission, curation, approval and publication, with decisions recorded and communicated.</p></article></section><section class="about-audiences"><article><h2>For artists and students</h2><p>Create a profile, build a portfolio and submit work to exhibitions that are open for entry. Every submission is reviewed by the gallery’s curators, and every decision is recorded with feedback.</p><button class="btn small" data-auth="register">Create an artist account</button></article><article><h2>For institutions</h2><p>Universities, galleries and cultural organizations can register for an institutional account, subject to approval by the ALU Gallery administration. Approved partners manage their own artists, artwork and submissions within a protected workspace.</p><button class="btn outline small" data-auth="register">Register an institution</button></article></section><section class="about-facts"><article><span>Location</span><p>African Leadership University, Kigali, Rwanda</p></article><article><span>Programmes</span><p>Exhibitions, artist talks, workshops and residencies</p></article><article><span>Network</span><p>Universities, galleries and cultural institutions</p></article></section><footer class="about-footer"><div class="about-footer-main"><div class="about-brand"><span class="about-brandmark">A</span><div><b>ALU Gallery</b><p>A digital home for African creative practice — connecting the African Leadership University with partner institutions, artists and audiences across the continent and beyond.</p></div></div><div><span class="about-footer-label">Visit</span><button data-go="Gallery">Explore Gallery</button><button data-go="Exhibitions">Exhibitions</button><button data-go="Events">Events</button></div><div><span class="about-footer-label">Community</span><button data-go="Artists">Artists</button><button data-go="Institutions">Institutions</button><button data-go="About">About ALU Gallery</button></div></div><div class="about-copyright">African Leadership University · Kigali, Rwanda</div></footer></div>`;}
function ensureAboutLink(){const host=document.querySelector('.topright');if(host&&!host.querySelector('[data-go="About"]')){const link=document.createElement('button');link.className='textbtn about-link';link.dataset.go='About';link.textContent='About';link.onclick=()=>go('About');host.prepend(link);}}
function render() {
  originalRender();
  ensureReportsNav();
  ensureUsersNav();
  ensureAboutLink();
  accountControls();
  document.body.classList.toggle('about-page',page==='About');
  if(page==='About'){document.querySelector('#crumb').textContent='About';document.querySelector('#app').innerHTML=aboutPage();bind();}
  document.querySelectorAll('.navbtn').forEach(item=>item.hidden=!permitted(item));
  if(role==='Institution admin'&&page==='Gallery') document.querySelector('.pagehead')?.insertAdjacentHTML('beforeend','<button class="btn" data-inst-submit>＋ Submit institutional artwork</button>');
  if(role==='Institution admin'&&page==='Events'){document.querySelector('.pagehead')?.insertAdjacentHTML('beforeend','<button class="btn" id="institutionCreateEvent">＋ Create event</button>');document.querySelector('#institutionCreateEvent').onclick=()=>modal('event');}
  const badge=document.querySelector('#notif .dot');
  if(badge) badge.hidden=!notifications.some(n=>!n.read);
  if(page==='Reports'){document.querySelector('#app').innerHTML=reportMarkup();const form=document.querySelector('#reportFilter');form.onsubmit=e=>{e.preventDefault();fetchReport(new FormData(form).get('from'),new FormData(form).get('to'));};document.querySelector('#exportReport').onclick=()=>{if(!reportData){toast('Load a report first.');return;}const lines=[['Metric','Value'],['Users',reportData.users],['Artists',reportData.artists],['Institutions',reportData.institutions],['Submissions',reportData.submissions],['Approved submissions',reportData.approved],['Events',reportData.events],[],['Month','Submissions'],...(reportData.monthly||[]).map(x=>[x.month,x.count])];const blob=new Blob([lines.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='alu-gallery-report.csv';a.click();URL.revokeObjectURL(a.href);};document.querySelector('#printReport').onclick=()=>print();if(!reportData)fetchReport();}
  if(page==='Users'){document.querySelector('#app').innerHTML=usersMarkup();const input=document.querySelector('#userSearch');input.oninput=()=>{const q=input.value.toLowerCase();document.querySelector('#userRows').innerHTML=userTable((userRecords||[]).filter(u=>`${u.fullName} ${u.email} ${u.role}`.toLowerCase().includes(q)));};if(!userRecords)loadUsers();}
  if(page==='Messages'&&signedUser&&!conversationsLoaded&&!conversationsLoading)loadConversations();
}

function submissionTable(rows,actions=false) {
  return `<div class="tablewrap"><table><thead><tr><th>Artwork</th><th>Artist</th><th>Exhibition</th><th>Date</th><th>Status</th>${actions?'<th>Review</th>':''}</tr></thead><tbody>${rows.map((s,i)=>`<tr><td>${esc(s.title)}</td><td>${esc(s.artist)}</td><td>${esc(s.exhibition)}</td><td>${esc(s.date||'Today')}</td><td>${stat(s.status)}${s.feedback?`<small class="reviewfeedback">${esc(s.feedback)}</small>`:''}</td>${actions?`<td class="reviewactions"><button class="textbtn" data-review-status="${i}" data-status="Approved">Approve</button><button class="textbtn" data-review-status="${i}" data-status="Changes requested">Request changes</button><button class="textbtn" data-review-status="${i}" data-status="Rejected">Reject</button></td>`:''}</tr>`).join('')||'<tr><td colspan="6">No submissions yet.</td></tr>'}</tbody></table></div>`;
}
function messages() {
  const active=conversations.find(c=>c.id===activeConversation);
  return `${head('Private workspace','Messages','Private conversations are shared only with their participants.')}<div class="panel messages"><div class="conversation-sidebar"><button class="btn small" data-new-conversation>＋ New message</button>${conversations.map(c=>`<button class="thread ${activeConversation===c.id?'active':''}" data-thread-id="${c.id}"><b>${esc(c.subject||'Conversation')}</b><small>${esc(c.created_at||'')}</small></button>`).join('')||'<div class="empty">No conversations yet.</div>'}</div><div class="chat">${active?`<h3 class="chat-title">${esc(active.subject||'Conversation')}</h3>`:'<p class="chat-title">Start a conversation</p>'}<div id="bubbles">${messageRows.map(m=>`<div class="bubble ${m.sender_id===signedUser?.id?'mine':''}">${esc(m.body)}<small>${esc(m.sender)} · ${esc(m.created_at)}</small></div>`).join('')||'<p class="empty">No messages yet.</p>'}</div><form class="chatform" id="chatform">${!active?`<select name="recipientId" aria-label="Message recipient" required><option value="">Choose a recipient</option>${contacts.map(c=>`<option value="${c.id}">${esc(c.fullName)} · ${esc(c.role.replace('_',' '))}</option>`).join('')}</select>`:''}<input name="message" placeholder="Write a message…" required maxlength="4000"><button class="btn small">Send</button></form></div></div>`;
}
const originalModal=modal;
function modal(type) {
  originalModal(type);
  const form=document.querySelector('#modalform');
  if(!form) return;
  if(['exhibition','institution','event','collab'].includes(type))form.onsubmit=null;
  if(type==='art') {
    form.onsubmit=null;
    const artist=form.querySelector('[name="artist"]');if(artist&&signedUser){artist.value=signedUser.fullName;artist.readOnly=true;}
    const category=form.querySelector('[name="category"]')?.closest('.field');if(category)category.innerHTML=`<label>Discipline</label><select name="category" required>${galleryDisciplines.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`;
    const imageField=[...form.querySelectorAll('.field')].find(f=>f.querySelector('[name="image"]'));
    if(imageField) imageField.innerHTML='<label>Artwork image (JPEG, PNG, WebP · max 2 MB)</label><input name="imageFile" type="file" accept="image/jpeg,image/png,image/webp" required>';
    const file=form.querySelector('[name="imageFile"]');
    file?.addEventListener('change',()=>{const f=file.files[0];if(f&&f.size>2*1024*1024){file.value='';toast('Please choose an image under 2 MB.');}});
    addFields(form,[['medium','Medium and materials'],['dimensions','Dimensions'],['creationDate','Creation date','date'],['tags','Artwork tags'],['copyright','Copyright / ownership']]);
  }
  if(type==='exhibition')addFields(form,[['description','Description','textarea'],['endsAt','Closing date','date'],['requirements','Submission requirements','textarea']]);
  if(type==='event')addFields(form,[['description','Event description','textarea'],['capacity','Registration limit','number']]);
  if(type==='institution')addFields(form,[['description','Institution description','textarea'],['website','Official website','url']]);
  if(type==='submission') {
    form.onsubmit=null;
    const title=form.querySelector('[name="title"]');
    if(title){const select=document.createElement('select');select.name='title';select.required=true;const items=db.artworks.filter(a=>(role==='Artist'&&a.ownerId===signedUser?.id)||(role==='Institution admin'&&a.institutionId===signedUser?.institutionId));select.innerHTML=items.map(a=>`<option>${esc(a.title)}</option>`).join('');title.replaceWith(select);}
    const exhibition=form.querySelector('[name="exhibition"]');
    if(exhibition){const select=document.createElement('select');select.name='exhibition';select.required=true;select.innerHTML=db.exhibitions.filter(e=>/submission/i.test(e.status)).map(e=>`<option>${esc(e.title)}</option>`).join('');if(!select.options.length)select.innerHTML='<option>General submission</option>';exhibition.replaceWith(select);}
    const artist=form.querySelector('[name="artist"]');
    if(artist&&role==='Artist'){artist.value=signedUser?.fullName||'';artist.readOnly=true;}
  }
  if(type==='collab'){
    const field=form.querySelector('[name="institution"]')?.closest('.field');
    const partnerOptions=db.institutions.filter(i=>i.status==='approved'&&i.id!==signedUser?.institutionId);
    if(field)field.innerHTML=`<label>Invited institution</label><select name="institutionId" required>${partnerOptions.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select>`;
    const exhibition=document.createElement('div');exhibition.className='field';exhibition.innerHTML=`<label>Collaborative exhibition</label><select name="exhibitionId"><option value="">Select later</option>${db.exhibitions.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select>`;form.querySelector('.formgrid').append(exhibition);
    if(role==='Gallery admin'){const organizer=document.createElement('div');organizer.className='field full';organizer.innerHTML=`<label>Organizing institution</label><select name="organizerInstitutionId" required>${db.institutions.filter(i=>i.status==='approved').map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select>`;form.querySelector('.formgrid').prepend(organizer);}
  }
  form.addEventListener('submit',async e=>{
    if(type==='art') {
      e.preventDefault(); const f=form.querySelector('[name="imageFile"]')?.files[0]; if(!f)return;
      if(f.size>2*1024*1024){toast('Please choose an image under 2 MB.');return;}
      const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>resolve(reader.result);reader.readAsDataURL(f);});
      const values=Object.fromEntries(new FormData(form));try{await api('/api/artworks',{method:'POST',body:JSON.stringify({title:values.title,category:values.category,description:values.description,medium:values.medium,dimensions:values.dimensions,creationDate:values.creationDate,tags:values.tags,copyright:values.copyright,imageData:data})});close();await refreshFromServer();toast('Artwork submitted for administrator review.');}catch(err){toast(err.message);}
    }
    if(type==='submission') {
      e.preventDefault();const values=Object.fromEntries(new FormData(form)),artwork=db.artworks.find(a=>a.title===values.title),exhibition=db.exhibitions.find(x=>x.title===values.exhibition);if(!artwork||!exhibition){toast('Choose your artwork and an open exhibition.');return;}try{await api('/api/submissions',{method:'POST',body:JSON.stringify({artworkId:artwork.id,exhibitionId:exhibition.id})});close();await refreshFromServer();toast('Submission sent for review.');}catch(err){toast(err.message);}
    }
    if(type==='exhibition'||type==='institution'||type==='event'||type==='collab'){
      e.preventDefault();const values=Object.fromEntries(new FormData(form));let endpoint, payload;
      if(type==='exhibition'){endpoint='/api/exhibitions';payload={title:values.title,theme:values.theme,description:values.description,startsAt:values.date,endsAt:values.endsAt,venue:values.place,requirements:values.requirements,status:String(values.status||'draft').toLowerCase()};}
      if(type==='institution'){endpoint='/api/institutions';payload={name:values.name,type:values.type,location:values.location,description:values.description,website:values.website};}
      if(type==='event'){endpoint='/api/events';payload={title:values.title,description:values.description,startsAt:values.date,venue:values.place,kind:values.kind,capacity:values.capacity,status:'registration open'};}
      if(type==='collab'){endpoint='/api/collaborations';payload={institutionId:Number(values.institutionId),organizerInstitutionId:Number(values.organizerInstitutionId||signedUser?.institutionId),exhibitionId:Number(values.exhibitionId)||null,message:values.detail};}
      try{await api(endpoint,{method:'POST',body:JSON.stringify(payload)});close();await refreshFromServer();toast('Saved successfully.');}catch(err){toast(err.message);}
    }
  },{once:true});
}
function addFields(form,fields){const grid=form.querySelector('.formgrid');for(const [name,label,type='text'] of fields){const field=document.createElement('div');field.className=`field ${type==='textarea'?'full':''}`;field.innerHTML=`<label>${label}</label>${type==='textarea'?`<textarea name="${name}"></textarea>`:`<input name="${name}" type="${type}" ${type==='number'?'min="1"':''}>`}`;grid.append(field);}}

// Keep the institution and artist views scoped to their own workspaces.
const originalSubmissions=window.__aluBaseSubmissions;
function submissions() {
  if(role==='Institution admin') return `${head('Institution workspace','Submissions','Artwork submitted by your institution.')}<div class="panel"><div class="panelhead"><h3>Institution activity</h3></div><div id="subtable">${submissionTable(db.submissions, false)}</div></div>`;
  if(role==='Artist') return `${head('Artist workspace','Artwork submissions','Submit work to an exhibition and follow review progress.',signedUser?'<button class="btn" data-modal="submission">＋ Submit artwork</button>':'')}<div class="panel"><div class="panelhead"><h3>Submission activity</h3></div><div id="subtable">${submissionTable(db.submissions,false)}</div></div>`;
  return originalSubmissions();
}
institutions=function(){
  const admin=role==='Gallery admin';
  const list=db.institutions.filter(i=>admin||i.status==='approved');
  return `${head('Our network','Partner institutions','A growing network of universities and cultural organizations.',admin?'<button class="btn" data-modal="institution">＋ Add institution</button>':'')}<div class="toolbar"><input id="search" class="search" placeholder="Search institutions" value="${esc(filter)}"></div><div class="grid">${list.filter(i=>i.name.toLowerCase().includes(filter.toLowerCase())).map(i=>`<article class="instcard"><div class="seal">${esc(i.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</div><h3>${esc(i.name)}</h3><p>${esc(i.type)} · ${esc(i.location)}</p><div class="instmeta"><span>${i.artists||0} affiliated artists</span>${stat(i.status||'approved')}</div>${admin&&i.status!=='approved'?`<div class="instactions"><button class="btn small" data-institution-status="approved" data-id="${i.id}">Approve</button><button class="btn outline small" data-institution-status="rejected" data-id="${i.id}">Reject</button></div>`:''}</article>`).join('')||'<div class="empty">No institutions found.</div>'}</div>`;
};
exhibitionPage=function(){const admin=role==='Gallery admin';return `${head('Curated experiences','Exhibitions','Explore open calls, published and archived exhibitions.',admin?'<button class="btn" data-modal="exhibition">＋ Create exhibition</button>':'')}<div class="grid">${db.exhibitions.map(x=>`<article class="instcard"><div class="eyebrow">${esc(x.status)}</div><h3>${esc(x.title)}</h3><p>${esc(x.theme)}<br>${esc(x.place)}<br>${esc(x.description||'')}</p><div class="instmeta"><span>${esc(x.date)}</span>${x.status.toLowerCase().includes('submissions')?'<button class="textbtn" data-submit>Submit work →</button>':''}</div>${admin?`<div class="instactions"><select class="filter" id="ex-status-${x.id}">${['draft','upcoming','open for submissions','published','ongoing','completed','archived'].map(s=>`<option value="${s}" ${s===x.status.toLowerCase()?'selected':''}>${s}</option>`).join('')}</select><button class="btn small" data-exhibition-update="${x.id}">Save status</button></div>`:''}</article>`).join('')||'<div class="empty">No exhibitions have been published.</div>'}</div>`;};
events=function(list){return list.length?`<div class="eventlist">${list.map(e=>`<div class="event"><div class="event-date">${esc(e.date)}</div><div><div class="datebox">${esc(e.kind||'Gallery event')} · ${e.registrations||0}${e.capacity?` / ${e.capacity}`:''} registered</div><h3>${esc(e.title)}</h3><p>${esc(e.place)} · ${esc(e.status)}</p></div><div class="eventactions"><button class="btn small ${e.registered?'outline':''}" data-event="${esc(e.title)}">${e.registered?'Cancel registration':'Register'}</button>${signedUser&&(role==='Gallery admin'||(role==='Institution admin'&&e.created_by===signedUser.id))?`<button class="textbtn" data-event-cancel="${e.id}">Cancel event</button>`:''}</div></div>`).join('')}</div>`:`<div class="home-empty event-empty"><div class="empty-symbol" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="5" y="7" width="22" height="20" rx="2"/><path d="M10 4v6m12-6v6M5 13h22m-16 5h4m-4 4h10"/></svg></div><div><h3>No upcoming events</h3><p>New talks, workshops and gallery gatherings will appear here as soon as they are published.</p></div>${role==='Gallery admin'||role==='Institution admin'?'<button class="btn small" data-modal="event">Create an event</button>':'<button class="textbtn" data-go="Events">Explore events</button>'}</div>`;};
home=function(){const featured=db.artworks.filter(a=>a.status==='Published').slice(0,10),upcoming=db.events.filter(e=>!['completed','cancelled'].includes(e.status.toLowerCase())),collectionAction=role==='Artist'?'<button class="btn small" data-modal="art">Add artwork</button>':role==='Institution admin'?'<button class="btn small" data-inst-submit>Submit artwork</button>':role==='Gallery admin'?'<button class="textbtn" data-go="Artists">Invite artists to contribute</button>':'<button class="btn small" data-auth="register">Join the community</button>';return `${head('African Leadership University','A space for art to connect us.','Discover the artists, ideas and shared perspectives shaping contemporary African art.')}<section class="hero"><div class="eyebrow">A living collection</div><h2>Art in conversation<br>with the world.</h2><p>Explore work from a growing community of artists, universities and cultural institutions across Africa.</p><button class="btn" data-go="Gallery">Explore the gallery →</button></section><div class="sectionhead"><h2>Selected works</h2><button class="textbtn" data-go="Gallery">View all works →</button></div>${featured.length?cards(featured):`<div class="home-empty collection-empty"><div class="empty-symbol" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="4" y="4" width="24" height="24" rx="2"/><path d="m6 24 7-8 5 5 3-4 5 7M11 11h.01"/></svg></div><div><h3>The collection is taking shape</h3><p>Approved and published artwork will be featured here. Browse the gallery to see what is available or join the community to contribute.</p></div>${collectionAction}</div>`}<div class="sectionhead"><h2>What's happening</h2><button class="textbtn" data-go="Events">All events →</button></div>${events(upcoming)}<footer class="footer"><span>© 2026 ALU Gallery · African Leadership University</span><span>Art, community and shared perspectives.</span></footer>`;};
collabs=function() {
  const actions=role==='Gallery admin';
  return `${head('Phase 2 · Collaboration','Working together','Build meaningful artistic partnerships across institutions.',role==='Institution admin'?'<button class="btn" data-modal="collab">＋ Propose collaboration</button>':'')}<div class="collabcall"><div><h3>Good art travels further together.</h3><p>Connect with partner institutions and create exhibitions that cross borders.</p></div><button class="btn" style="background:white;color:#102a43" data-modal="collab">Start a conversation</button></div><div class="panel"><div class="panelhead"><h3>Partnership requests</h3></div><div class="tablewrap"><table><thead><tr><th>Institution</th><th>Request</th><th>Details</th><th>Status</th>${actions?'<th>Action</th>':''}</tr></thead><tbody>${db.requests.map((r,i)=>`<tr><td>${esc(r.institution)}</td><td>${esc(r.type)}</td><td>${esc(r.detail)}</td><td>${stat(r.status)}</td>${actions?`<td><button class="textbtn" data-request-status="${i}" data-status="Accepted">Accept</button><button class="textbtn" data-request-status="${i}" data-status="Declined">Decline</button></td>`:''}</tr>`).join('')||'<tr><td colspan="5">No requests yet.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panelhead"><h3>Partner network</h3><button class="textbtn" data-go="Institutions">Browse institutions →</button></div><div class="grid">${db.institutions.map(i=>`<div><b>${esc(i.name)}</b><p>${esc(i.location)}</p></div>`).join('')}</div></div>`;
};
