const roleSelect=document.querySelector('#roleSelect');if(roleSelect)roleSelect.onchange=null;
document.querySelector('#notif').onclick=async()=>{if(signedUser){try{await api('/api/notifications/read');}catch{}}showNotifications();};
document.addEventListener('click',e=>{
  const editArt=e.target.closest('[data-art-edit]');if(editArt){editArtwork(editArt.dataset.artEdit);return;}
  const deleteArt=e.target.closest('[data-art-delete]');if(deleteArt){const art=db.artworks.find(x=>x.id===Number(deleteArt.dataset.artDelete));if(!art||!confirm(`Remove “${art.title}” from the gallery? Its submission records will also be removed.`))return;(async()=>{try{await api(`/api/artworks/${art.id}`,{method:'DELETE'});await refreshFromServer();toast('Artwork removed.');}catch(err){toast(err.message);}})();return;}
  const auth=e.target.closest('[data-auth]');if(auth){authDialog(auth.dataset.auth);return;}
  if(e.target.closest('[data-inst-submit]')){modal('submission');return;}
  const review=e.target.closest('[data-review-status]');
  if(review){const s=db.submissions[Number(review.dataset.reviewStatus)],status=review.dataset.status.toLowerCase();if(s)(async()=>{try{await api(`/api/submissions/${s.id}`,{method:'PATCH',body:JSON.stringify({status,feedback:status==='changes requested'?'Please update the artwork details and resubmit.':''})});await refreshFromServer();toast(`Submission ${status}.`);}catch(err){toast(err.message);}})();return;}
  const thread=e.target.closest('[data-thread-name]');
  if(thread){activeConversation=thread.dataset.threadName;render();}
  const threadId=e.target.closest('[data-thread-id]');
  if(threadId){activeConversation=Number(threadId.dataset.threadId);messageRows=[];conversationsLoaded=false;loadConversations();return;}
  if(e.target.closest('[data-new-conversation]')){activeConversation=null;messageRows=[];conversationsLoaded=true;render();return;}
  const request=e.target.closest('[data-request-status]');
  if(request){const record=db.requests[Number(request.dataset.requestStatus)];if(record)(async()=>{try{await api(`/api/collaborations/${record.id}`,{method:'PATCH',body:JSON.stringify({status:request.dataset.status.toLowerCase()})});await refreshFromServer();toast(`Request ${request.dataset.status.toLowerCase()}.`);}catch(err){toast(err.message);}})();return;}
  const institution=e.target.closest('[data-institution-status]');
  if(institution)(async()=>{try{await api(`/api/institutions/${institution.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:institution.dataset.institutionStatus})});await refreshFromServer();toast(`Institution ${institution.dataset.institutionStatus}.`);}catch(err){toast(err.message);}})();
  const user=e.target.closest('[data-user-status]');
  if(user)(async()=>{try{await api(`/api/users/${user.dataset.userStatus}`,{method:'PATCH',body:JSON.stringify({status:user.dataset.status})});userRecords=null;await loadUsers();toast('Account access updated.');}catch(err){toast(err.message);}})();
  const exhibition=e.target.closest('[data-exhibition-update]');
  if(exhibition){const status=document.querySelector(`#ex-status-${exhibition.dataset.exhibitionUpdate}`)?.value;(async()=>{try{await api(`/api/exhibitions/${exhibition.dataset.exhibitionUpdate}`,{method:'PATCH',body:JSON.stringify({status})});await refreshFromServer();toast('Exhibition status updated.');}catch(err){toast(err.message);}})();}
  const eventCancel=e.target.closest('[data-event-cancel]');
  if(eventCancel)(async()=>{if(!confirm('Cancel this event? Registered participants will be notified.'))return;try{await api(`/api/events/${eventCancel.dataset.eventCancel}`,{method:'PATCH',body:JSON.stringify({status:'cancelled'})});await refreshFromServer();toast('Event cancelled.');}catch(err){toast(err.message);}})();
  const art=e.target.closest('.artcard');
  if(art&&!e.target.closest('button')){const title=art.querySelector('h3')?.textContent,a=db.artworks.find(x=>x.title===title);if(a)showArtwork(a);}
});
document.addEventListener('submit',e=>{
  if(e.target.id==='chatform'){e.preventDefault();if(!signedUser){authDialog('login');return;}const formData=new FormData(e.target),text=String(formData.get('message')||'').trim(),payload={body:text};if(activeConversation)payload.conversationId=activeConversation;else payload.recipientId=Number(formData.get('recipientId'));if(!text||(!activeConversation&&!payload.recipientId))return;(async()=>{try{const result=await api('/api/messages',{method:'POST',body:JSON.stringify(payload)});activeConversation=result.conversationId;conversationsLoaded=false;await loadConversations();}catch(err){toast(err.message);}})();}
});
const baseBind=bind;
bind=function(){baseBind();const chat=document.querySelector('#chatform');if(chat)chat.onsubmit=null;document.querySelectorAll('[data-thread-name]').forEach(b=>b.onclick=()=>{activeConversation=b.dataset.threadName;render();});document.querySelectorAll('[data-submit]').forEach(b=>b.onclick=()=>signedUser?modal('submission'):authDialog('login'));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{if(!signedUser){authDialog('login');return;}const event=db.events.find(x=>x.title===b.dataset.event);if(!event)return;(async()=>{try{await api(`/api/events/${event.id}/register`,{method:event.registered?'DELETE':'POST',body:'{}'});await refreshFromServer();toast(event.registered?'Registration cancelled.':'You are registered.');}catch(err){toast(err.message);}})();});const filters=['catfilter','artistfilter','institutionfilter'].map(id=>document.querySelector(`#${id}`)).filter(Boolean);filters.forEach(x=>x.onchange=()=>{galleryFilters.category=document.querySelector('#catfilter')?.value||'';galleryFilters.artist=document.querySelector('#artistfilter')?.value||'';galleryFilters.institution=document.querySelector('#institutionfilter')?.value||'';const q=(document.querySelector('#search')?.value||'').toLowerCase(),list=db.artworks.filter(a=>a.status==='Published'&&`${a.title} ${a.artist} ${a.category} ${a.institution||''}`.toLowerCase().includes(q)&&(!galleryFilters.category||a.category===galleryFilters.category)&&(!galleryFilters.artist||a.artist===galleryFilters.artist)&&(!galleryFilters.institution||a.institution===galleryFilters.institution));const target=document.querySelector('.gallery-results');if(target)target.innerHTML=cards(list);});};
db=hydrateData(window.__ALU_BOOTSTRAP__||{});
render();
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
